import React from "react";
import { useDispatch, useSelector } from "react-redux";
import { Link, useNavigate } from "react-router-dom";
import { Navbar, Nav, NavItem, NavLink, Button } from "reactstrap";
import { logout } from "../Features/UserSlice";
import logo from "../Images/logo-side.png"; // غيري المسار إذا الصورة في مكان مختلف
import "../Styles/Header.css";

const Header = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  // ✅ نجيب المستخدم والدور من Redux
  const { user, isSuccess } = useSelector((state) => state.users);

  // 🔹 تسجيل الخروج
  const handleLogout = async () => {
    dispatch(logout());
    await new Promise((resolve) => setTimeout(resolve, 100));
    navigate("/login");
  };

  // 🔹 منع الدخول بدون تسجيل
  const handleProtectedClick = (path) => {
    if (!isSuccess || !user || !user.email) {
      alert("⚠️ You must log in to access this page.");
      navigate("/login");
    } else {
      navigate(path);
    }
  };

  return (
    <Navbar className="header" expand="md">
      {/* ✅ شعار الموقع */}
      <Nav className="me-auto" navbar>
        <NavItem>
          <img src={logo} alt="UTAS Link Logo" className="nav-logo" />
        </NavItem>

        {/* 🏠 الصفحة الرئيسية */}
        <NavItem>
          <NavLink tag={Link} to="/" className="nav-link">
            Home
          </NavLink>
        </NavItem>

        {/* 👩‍🎓 روابط الطالب */}
        {user?.role === "student" && (
          <>
            <NavItem>
              <NavLink
                className="nav-link"
                onClick={() => handleProtectedClick("/findjob")}
              >
                Find Job
              </NavLink>
            </NavItem>

            <NavItem>
              <NavLink
                className="nav-link"
                onClick={() => handleProtectedClick("/myapplications")}
              >
                My Applications
              </NavLink>
            </NavItem>

            <NavItem>
              <NavLink
                className="nav-link"
                onClick={() => handleProtectedClick("/userprofile")}
              >
                Profile
              </NavLink>
            </NavItem>

            <NavItem>
              <Button color="danger" size="sm" onClick={handleLogout}>
                Logout
              </Button>
            </NavItem>
          </>
        )}

        {/* 🏢 روابط الشركة */}
        {user?.role === "company" && (
          <>
            <NavItem>
              <NavLink
                className="nav-link"
                onClick={() => handleProtectedClick("/companyprofile")}
              >
                Company Profile
              </NavLink>
            </NavItem>

            <NavItem>
              <NavLink
                className="nav-link"
                onClick={() => handleProtectedClick("/postjob")}
              >
                Post Job
              </NavLink>
            </NavItem>

            <NavItem>
              <NavLink
                className="nav-link"
                onClick={() => handleProtectedClick("/companyjobs")}
              >
                My Jobs
              </NavLink>
            </NavItem>

            <NavItem>
              <NavLink
                className="nav-link"
                onClick={() => handleProtectedClick("/applicantsjob")}
              >
                Applicants
              </NavLink>
            </NavItem>

            <NavItem>
              <NavLink
                className="nav-link"
                onClick={() => handleProtectedClick("/chatpage")}
              >
                Chat
              </NavLink>
            </NavItem>

            <NavItem>
              <Button color="danger" size="sm" onClick={handleLogout}>
                Logout
              </Button>
            </NavItem>
          </>
        )}

        {/* 🚪 روابط المستخدم غير المسجل */}
        {!user?.email && (
          <>
            <NavItem>
              <NavLink tag={Link} to="/login" className="nav-link">
                Login
              </NavLink>
            </NavItem>
            <NavItem>
              <NavLink tag={Link} to="/user-register" className="nav-link">
                Register
              </NavLink>
            </NavItem>
          </>
        )}
      </Nav>
    </Navbar>
  );
};

export default Header;
